export interface NigerMapAccentProps {
  width?: number | string;
  height?: number | string;
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
  opacity?: number;
  variant?: 'fill' | 'outline';
  ariaLabel?: string;
  style?: React.CSSProperties;
}

/**
 * Composant Niger réutilisable, vectoriel.
 * Deux variantes :
 *  - 'fill'    : aplat coloré (utile en filigrane cover)
 *  - 'outline' : trait seul (utile en séparateur ou marque footer)
 */
export function NigerMapAccent({
  width = 200,
  height,
  fill = '#d4a843',
  stroke = '#d4a843',
  strokeWidth = 2,
  opacity = 1,
  variant = 'fill',
  ariaLabel = 'Contour du Niger',
  style,
}: NigerMapAccentProps) {
  const isOutline = variant === 'outline';
  return (
    <svg
      role="img"
      aria-label={ariaLabel}
      width={width}
      height={height ?? 'auto'}
      viewBox="0 0 1000 748"
      xmlns="http://www.w3.org/2000/svg"
      style={{
        display: 'block',
        opacity,
        ...style,
      }}
    >
      <path
        d={NIGER_PATH}
        fill={isOutline ? 'none' : fill}
        stroke={isOutline ? stroke : 'none'}
        strokeWidth={isOutline ? strokeWidth : 0}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </svg>
  );
}

export const NIGER_OUTLINE_PATH = NIGER_PATH;
